pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    let body = bytes.trim();

    if body == "ping" || body == r#"{"version":1,"type":"ping"}"# {
        return Ok(Msg::Ping);
    }

    if let Some(value) = body
        .strip_prefix(r#"{"v":2,"type":"hello","value":""#)
        .and_then(|body| body.strip_suffix(r#""}"#))
    {
        return unescape_json(value).map(Msg::Hello);
    }

    eprintln!("decode error: unknown message body: {body:?}");
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => r#"{"version":1,"type":"ping"}"#.into(),
        Msg::Hello(value) => format!(
            r#"{{"v":2,"type":"hello","value":"{}"}}"#,
            escape_json(value)
        ),
    }
}

fn escape_json(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => escaped.push_str(r#"\""#),
            '\\' => escaped.push_str(r#"\\"#),
            '\n' => escaped.push_str(r#"\n"#),
            '\r' => escaped.push_str(r#"\r"#),
            '\t' => escaped.push_str(r#"\t"#),
            character if character.is_control() => {
                escaped.push_str(&format!(r#"\u{:04x}"#, character as u32));
            }
            character => escaped.push(character),
        }
    }
    escaped
}

fn unescape_json(value: &str) -> Result<String, String> {
    let mut unescaped = String::with_capacity(value.len());
    let mut characters = value.chars();
    while let Some(character) = characters.next() {
        if character != '\\' {
            unescaped.push(character);
            continue;
        }

        match characters.next() {
            Some('"') => unescaped.push('"'),
            Some('\\') => unescaped.push('\\'),
            Some('/') => unescaped.push('/'),
            Some('b') => unescaped.push('\u{0008}'),
            Some('f') => unescaped.push('\u{000c}'),
            Some('n') => unescaped.push('\n'),
            Some('r') => unescaped.push('\r'),
            Some('t') => unescaped.push('\t'),
            _ => return Err("unknown".into()),
        }
    }
    Ok(unescaped)
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_bodies() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
        assert!(matches!(
            decode(r#" {"version":1,"type":"ping"} "#),
            Ok(Msg::Ping)
        ));
    }

    #[test]
    fn decodes_a_v2_hello() {
        assert!(matches!(
            decode(r#" {"v":2,"type":"hello","value":"client"} "#),
            Ok(Msg::Hello(value)) if value == "client"
        ));
    }

    #[test]
    fn encodes_versioned_messages() {
        assert_eq!(encode(&Msg::Ping), r#"{"version":1,"type":"ping"}"#);
        assert_eq!(
            encode(&Msg::Hello("client".into())),
            r#"{"v":2,"type":"hello","value":"client"}"#
        );
    }

    #[test]
    fn roundtrips_messages() {
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
        assert!(matches!(
            decode(&encode(&Msg::Hello("a \"quoted\" value".into()))),
            Ok(Msg::Hello(value)) if value == "a \"quoted\" value"
        ));
    }

    #[test]
    fn rejects_unrecognized_bodies() {
        assert!(decode("not-ping").is_err());
        assert!(decode(r#"{"version":2,"type":"ping"}"#).is_err());
        assert!(decode(r#"{"v":1,"type":"hello","value":"client"}"#).is_err());
    }
}

